<script defer>(function(){'use strict';const csrf=document.querySelector('meta[name="csrf-token"]')?.content||'',tree=document.getElementById('menu-tree'),root=document.getElementById('root-drop-zone'),form=document.getElementById('add-form');if(!tree||!form)return;const state=document.getElementById('save-state'),saveBtn=document.getElementById('save-tree');let dragged=null;function mark(t,s){state.className='save-indicator '+(t||'');state.innerHTML='<i class="fa-solid '+(t==='saving'?'fa-spinner fa-spin':t==='error'?'fa-circle-exclamation':'fa-circle-check')+'"></i><span>'+s+'</span>'}function clear(){tree.querySelectorAll('.menu-row').forEach(x=>x.classList.remove('drop-before','drop-after','drop-inside'));root?.classList.remove('drop-active')}function rows(c){return Array.from(c.children).filter(x=>x.classList.contains('menu-row'))}function serialize(c){const p=c.dataset.parentId?Number(c.dataset.parentId):null,r=[];rows(c).forEach((row,i)=>{r.push({id:Number(row.dataset.id),parent_id:p,sort_order:i});const kids=row.querySelector(':scope > .menu-children');if(kids)r.push(...serialize(kids))});return r}function childOf(row,id){return Array.from(row.querySelectorAll('.menu-row')).some(x=>Number(x.dataset.id)===id)}async function save(){mark('saving','Saving structure…');saveBtn.disabled=true;try{const res=await fetch('{{ route('admin.navigation.reorder') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({menu:@json($menu),tree:serialize(tree)})}),data=await res.json().catch(()=>({}));if(!res.ok||!data.ok)throw Error(data.message||'Could not save structure.');mark('','All changes saved');return true}catch(e){console.error(e);mark('error',e.message||'Could not save structure');return false}finally{saveBtn.disabled=false}}saveBtn?.addEventListener('click',save);tree.querySelectorAll('.menu-row[draggable="true"]').forEach(row=>{row.addEventListener('dragstart',e=>{dragged=row;row.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',row.dataset.id)});row.addEventListener('dragend',()=>{row.classList.remove('dragging');dragged=null;clear()});row.addEventListener('dragover',e=>{if(!dragged||dragged===row||childOf(dragged,Number(row.dataset.id)))return;e.preventDefault();clear();const card=row.querySelector(':scope > .menu-card'),rect=card.getBoundingClientRect(),y=e.clientY-rect.top;if(row.dataset.kind==='folder'&&y>rect.height*.25&&y<rect.height*.75)row.classList.add('drop-inside');else if(y<rect.height/2)row.classList.add('drop-before');else row.classList.add('drop-after')});row.addEventListener('drop',async e=>{if(!dragged||dragged===row||childOf(dragged,Number(row.dataset.id)))return;e.preventDefault();const card=row.querySelector(':scope > .menu-card'),rect=card.getBoundingClientRect(),y=e.clientY-rect.top,kind=row.dataset.kind;clear();if(kind==='folder'&&y>rect.height*.25&&y<rect.height*.75){let kids=row.querySelector(':scope > .menu-children');if(!kids){kids=document.createElement('div');kids.className='menu-children';kids.dataset.parentId=row.dataset.id;row.appendChild(kids)}kids.appendChild(dragged)}else{const p=row.parentElement;if(y<rect.height/2)p.insertBefore(dragged,row);else p.insertBefore(dragged,row.nextSibling)}await save()})});root?.addEventListener('dragover',e=>{if(!dragged)return;e.preventDefault();clear();root.classList.add('drop-active')});root?.addEventListener('drop',async e=>{if(!dragged)return;e.preventDefault();clear();tree.appendChild(dragged);await save()});
const modes=form.querySelectorAll('.add-mode-btn'),kind=form.querySelector('#kind'),sf=form.querySelector('#source-fields'),uf=form.querySelector('#url-fields'),ff=form.querySelector('#folder-fields'),sel=form.querySelector('#source-select'),sk=form.querySelector('#source-key'),sp=form.querySelector('#source-preview'),ul=form.querySelector('#url-label'),uv=form.querySelector('#url-value'),up=form.querySelector('#url-preview'),fl=form.querySelector('#folder-label'),add=form.querySelector('#add-button');let mode='source';function valid(){add.disabled=mode==='source'?!sk.value:mode==='url'?!ul.value.trim()||!uv.value.trim():!fl.value.trim()}function setMode(m){mode=m;kind.value=m;modes.forEach(b=>b.classList.toggle('active',b.dataset.mode===m));sf.classList.toggle('is-hidden',m!=='source');uf.classList.toggle('is-hidden',m!=='url');ff.classList.toggle('is-hidden',m!=='folder');valid()}modes.forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));sel?.addEventListener('change',()=>{const o=sel.options[sel.selectedIndex];sk.value=sel.value;sp.textContent=sel.value?o.dataset.label+' → '+o.dataset.url:'Select a destination to continue.';valid()});ul?.addEventListener('input',valid);uv?.addEventListener('input',()=>{up.textContent=uv.value.trim()||'Enter a URL to preview it.';valid()});fl?.addEventListener('input',valid);form.addEventListener('submit',()=>{add.disabled=true;add.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Adding…'});setMode('source')})();</script>
